// Generated by the Firenook console from saved rules tests.
// 11 tests against firestore.rules.
// Run with the Firestore emulator up, for example:
//   firebase emulators:exec --only firestore "npx vitest run"
// Documents the rules read with get() or exists() are not set up here;
// add them in beforeEach when a test depends on one.
import { readFileSync } from 'node:fs'
import { afterAll, beforeAll, beforeEach, test } from 'vitest'
import {
  assertFails,
  assertSucceeds,
  initializeTestEnvironment,
  type RulesTestEnvironment,
} from '@firebase/rules-unit-testing'
import {
  Bytes,
  GeoPoint,
  Timestamp,
  collection,
  collectionGroup,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  limit,
  orderBy,
  query,
  setDoc,
  updateDoc,
  vector,
  where,
} from 'firebase/firestore'

let env: RulesTestEnvironment

beforeAll(async () => {
  env = await initializeTestEnvironment({
    projectId: "demo-firenook-rules-testing",
    firestore: { rules: readFileSync("firestore.rules", 'utf8') },
  })
})

afterAll(() => env.cleanup())
beforeEach(() => env.clearFirestore())

test("alice reads her profile is allowed", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "users/alice"), { name: "Alice" })
  })
  const db = env.authenticatedContext("alice", {}).firestore()
  await assertSucceeds(getDoc(doc(db, "users/alice")))
})

test("bob reads alice is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "users/alice"), { name: "Alice" })
  })
  const db = env.authenticatedContext("bob", {}).firestore()
  await assertFails(getDoc(doc(db, "users/alice")))
})

test("signed out reads alice is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "users/alice"), { name: "Alice" })
  })
  const db = env.unauthenticatedContext().firestore()
  await assertFails(getDoc(doc(db, "users/alice")))
})

test("signed out reads a post is allowed", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "posts/p1"), { author: "alice", title: "Hello" })
  })
  const db = env.unauthenticatedContext().firestore()
  await assertSucceeds(getDoc(doc(db, "posts/p1")))
})

test("alice posts as herself is allowed", async () => {
  const db = env.authenticatedContext("alice", {}).firestore()
  await assertSucceeds(setDoc(doc(db, "posts/p2"), { author: "alice", title: "Hi" }))
})

test("alice posts as bob is denied", async () => {
  const db = env.authenticatedContext("alice", {}).firestore()
  await assertFails(setDoc(doc(db, "posts/p3"), { author: "bob", title: "Hi" }))
})

test("bob edits alice is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "posts/p1"), { author: "alice", title: "Hello" })
  })
  const db = env.authenticatedContext("bob", {}).firestore()
  await assertFails(updateDoc(doc(db, "posts/p1"), { title: "Mine" }))
})

test("an admin reads settings is allowed", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "admin/settings"), { open: true })
  })
  const db = env.authenticatedContext("carol", {"admin":true}).firestore()
  await assertSucceeds(getDoc(doc(db, "admin/settings")))
})

test("alice reads settings is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const db = context.firestore()
    await setDoc(doc(db, "admin/settings"), { open: true })
  })
  const db = env.authenticatedContext("alice", {}).firestore()
  await assertFails(getDoc(doc(db, "admin/settings")))
})

test("signed out lists posts is allowed", async () => {
  const db = env.unauthenticatedContext().firestore()
  await assertSucceeds(getDocs(collection(db, "posts")))
})

test("signed out lists users is denied", async () => {
  const db = env.unauthenticatedContext().firestore()
  await assertFails(getDocs(collection(db, "users")))
})
